#!/usr/bin/env node
// Embeds the authored MCP Apps widget (src/mcp-ui/upload.html) into a generated
// TypeScript module. Bundlers that inline server sources (the private app's
// Vite SSR build) cannot resolve a sibling .html file at runtime, so the server
// imports this module instead of reading the file.
//
//   pnpm -C server build:mcp-ui          write src/mcp-ui/upload-bundle.generated.ts
//   pnpm -C server build:mcp-ui --check  exit 1 when the generated file is stale
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const source = fileURLToPath(new URL("../src/mcp-ui/upload.html", import.meta.url));
const target = fileURLToPath(new URL("../src/mcp-ui/upload-bundle.generated.ts", import.meta.url));

const html = readFileSync(source, "utf8");
const sha256 = createHash("sha256").update(html, "utf8").digest("hex");
const output = [
  "// GENERATED by server/scripts/build-mcp-ui.mjs from upload.html. Do not edit; run `pnpm -C server build:mcp-ui`.",
  "// The hash covers the authored template (before connect-src substitution) and versions the ui:// resource URI.",
  `export const UPLOAD_HTML = ${JSON.stringify(html)};`,
  `export const UPLOAD_HTML_SHA256 = ${JSON.stringify(sha256)};`,
  "",
].join("\n");

if (process.argv.includes("--check")) {
  let current = "";
  try { current = readFileSync(target, "utf8"); } catch {}
  if (current !== output) {
    console.error("upload-bundle.generated.ts is out of date. Run: pnpm -C server build:mcp-ui");
    process.exit(1);
  }
  console.log(`upload-bundle.generated.ts is current (${sha256.slice(0, 12)})`);
} else {
  writeFileSync(target, output);
  console.log(`wrote ${target} (${html.length} chars, sha256 ${sha256.slice(0, 12)})`);
}
